import os
from typing import Any, Dict, Optional, Sequence, Tuple

import numpy as np
import torch
from PIL import Image
from torch.utils.data import ConcatDataset, Dataset, Subset
from torchvision import datasets as torchvision_datasets
from torchvision import transforms


DATA_CONFIG = {
    "primary": {
        "name": "Split CIFAR-100",
        "role": "primary",
        "num_classes": 100,
        "native_input_shape": (3, 32, 32),
        "model_input_shape": (3, 224, 224),
        "task_protocols": {
            "10_tasks": {"num_tasks": 10, "classes_per_task": 10},
            "20_tasks": {"num_tasks": 20, "classes_per_task": 5},
        },
        "default_protocol": "10_tasks",
        "metrics": [
            "average_accuracy",
            "forgetting_rate",
            "backward_transfer",
        ],
    },
    "secondary": {
        "name": "CIFAR-10-C",
        "role": "secondary",
        "num_classes": 10,
        "native_input_shape": (3, 32, 32),
        "model_input_shape": (3, 224, 224),
        "num_corruption_types": 15,
        "num_severity_levels": 5,
        "metrics": ["accuracy", "mean_corruption_error"],
    },
    "normalization": {
        "mean": (0.485, 0.456, 0.406),
        "std": (0.229, 0.224, 0.225),
    },
    "validation_fraction": 0.1,
    "split_seed": 42,
}


class TaggedDataset(Dataset):
    def __init__(
        self,
        dataset: Dataset,
        source: str,
        task_ids: Optional[Sequence[int]] = None,
    ) -> None:
        self.dataset = dataset
        self.source = source
        self.task_ids = task_ids

        if task_ids is not None and len(task_ids) != len(dataset):
            raise ValueError(
                f"task_ids length ({len(task_ids)}) does not match dataset "
                f"length ({len(dataset)})."
            )

    def __len__(self) -> int:
        return len(self.dataset)

    def __getitem__(self, index: int) -> Dict[str, Any]:
        sample = self.dataset[index]

        if isinstance(sample, dict):
            if "image" not in sample or "label" not in sample:
                raise KeyError(
                    "Dictionary samples must contain 'image' and 'label'."
                )
            result = dict(sample)
        else:
            if not isinstance(sample, (tuple, list)) or len(sample) < 2:
                raise TypeError(
                    "Dataset samples must be dictionaries or (image, label) tuples."
                )
            result = {
                "image": sample[0],
                "label": int(sample[1]),
            }

        result["source"] = self.source

        if self.task_ids is not None:
            result["task_id"] = int(self.task_ids[index])

        return result


class HuggingFaceImageDataset(Dataset):
    def __init__(self, dataset: Any, transform: transforms.Compose) -> None:
        self.dataset = dataset
        self.transform = transform

    def __len__(self) -> int:
        return len(self.dataset)

    @staticmethod
    def _find_field(
        example: Dict[str, Any],
        candidates: Tuple[str, ...],
    ) -> Tuple[str, Any]:
        for name in candidates:
            if name in example:
                return name, example[name]
        raise KeyError(
            f"None of the expected fields {candidates} are present. "
            f"Available fields: {sorted(example.keys())}"
        )

    def __getitem__(self, index: int) -> Dict[str, Any]:
        example = self.dataset[index]
        _, image = self._find_field(example, ("image", "img"))
        _, label = self._find_field(
            example,
            ("label", "labels", "fine_label"),
        )

        if isinstance(image, torch.Tensor):
            image = image.detach().cpu()
            image = transforms.functional.to_pil_image(image)
        elif isinstance(image, np.ndarray):
            image = transforms.functional.to_pil_image(image)
        elif not isinstance(image, Image.Image):
            try:
                image = Image.open(image).convert("RGB")
            except Exception as exc:
                raise TypeError(
                    f"Unsupported image type at index {index}: {type(image)!r}"
                ) from exc

        image = image.convert("RGB")

        output = {
            "image": self.transform(image),
            "label": int(label),
        }

        for field in (
            "corruption",
            "corruption_type",
            "severity",
            "distortion",
        ):
            if field in example:
                value = example[field]
                if isinstance(value, torch.Tensor) and value.numel() == 1:
                    value = value.item()
                output[field] = value

        return output


def _make_stratified_split(
    targets: Sequence[int],
    validation_fraction: float,
    seed: int,
) -> Tuple[list, list]:
    if not 0.0 < validation_fraction < 1.0:
        raise ValueError("validation_fraction must be between 0 and 1.")

    targets_array = np.asarray(targets, dtype=np.int64)
    generator = np.random.default_rng(seed)
    train_indices = []
    validation_indices = []

    for class_id in np.unique(targets_array):
        class_indices = np.flatnonzero(targets_array == class_id)
        generator.shuffle(class_indices)

        validation_count = max(
            1,
            int(round(len(class_indices) * validation_fraction)),
        )
        validation_indices.extend(class_indices[:validation_count].tolist())
        train_indices.extend(class_indices[validation_count:].tolist())

    generator.shuffle(train_indices)
    generator.shuffle(validation_indices)
    return train_indices, validation_indices


def _select_huggingface_evaluation_split(dataset_object: Any) -> Any:
    if not hasattr(dataset_object, "keys"):
        return dataset_object

    for split_name in ("test", "validation", "train"):
        if split_name in dataset_object:
            return dataset_object[split_name]

    available_splits = list(dataset_object.keys())
    if not available_splits:
        raise ValueError("The HuggingFace CIFAR-10-C dataset has no splits.")

    return dataset_object[available_splits[0]]


def _load_cached_cifar10c(
    data_root: str,
    transform: transforms.Compose,
) -> Dataset:
    try:
        from datasets import DownloadMode, load_dataset
    except ImportError as exc:
        raise ImportError(
            "CIFAR-10-C requires the optional HuggingFace 'datasets' package. "
            "Install it in setup.py before running the experiment."
        ) from exc

    cache_dir = os.path.join(data_root, "hf")
    if not os.path.isdir(cache_dir):
        raise FileNotFoundError(
            f"CIFAR-10-C cache directory does not exist: {cache_dir!r}. "
            "Run setup.py with network access and call "
            "load_dataset('cifar10_corrupted', cache_dir="
            f"{cache_dir!r}) before running the offline experiment."
        )

    previous_offline_setting = os.environ.get("HF_DATASETS_OFFLINE")
    os.environ["HF_DATASETS_OFFLINE"] = "1"

    try:
        dataset_object = load_dataset(
            "cifar10_corrupted",
            cache_dir=cache_dir,
            download_mode=DownloadMode.REUSE_DATASET_IF_EXISTS,
        )
    except Exception as exc:
        raise RuntimeError(
            "Unable to load cached CIFAR-10-C. The experiment does not download "
            "Tier-2 datasets at runtime. Run setup.py with network access using "
            "datasets.load_dataset('cifar10_corrupted', "
            f"cache_dir={cache_dir!r}). Original error: {exc}"
        ) from exc
    finally:
        if previous_offline_setting is None:
            os.environ.pop("HF_DATASETS_OFFLINE", None)
        else:
            os.environ["HF_DATASETS_OFFLINE"] = previous_offline_setting

    evaluation_split = _select_huggingface_evaluation_split(dataset_object)
    return HuggingFaceImageDataset(
        evaluation_split,
        transform=transform,
    )


def get_datasets(data_root: str = "/workspace/data") -> dict:
    if not isinstance(data_root, str) or not data_root:
        raise ValueError("data_root must be a non-empty path string.")

    mean = DATA_CONFIG["normalization"]["mean"]
    std = DATA_CONFIG["normalization"]["std"]

    train_transform = transforms.Compose(
        [
            transforms.RandomResizedCrop(
                size=224,
                scale=(0.7, 1.0),
                interpolation=transforms.InterpolationMode.BICUBIC,
                antialias=True,
            ),
            transforms.RandomHorizontalFlip(p=0.5),
            transforms.RandAugment(num_ops=2, magnitude=9),
            transforms.ToTensor(),
            transforms.Normalize(mean=mean, std=std),
        ]
    )

    evaluation_transform = transforms.Compose(
        [
            transforms.Resize(
                size=(224, 224),
                interpolation=transforms.InterpolationMode.BICUBIC,
                antialias=True,
            ),
            transforms.ToTensor(),
            transforms.Normalize(mean=mean, std=std),
        ]
    )

    try:
        augmented_training_dataset = torchvision_datasets.CIFAR100(
            root=data_root,
            train=True,
            transform=train_transform,
            download=False,
        )
        evaluation_training_dataset = torchvision_datasets.CIFAR100(
            root=data_root,
            train=True,
            transform=evaluation_transform,
            download=False,
        )
        clean_test_dataset = torchvision_datasets.CIFAR100(
            root=data_root,
            train=False,
            transform=evaluation_transform,
            download=False,
        )
    except RuntimeError as exc:
        raise FileNotFoundError(
            f"Pre-cached CIFAR-100 was not found under {data_root!r}. "
            "Tier-1 datasets must be prepared in advance and are always loaded "
            f"with download=False. Original error: {exc}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(
            f"Failed to initialize CIFAR-100 from {data_root!r}: {exc}"
        ) from exc

    train_indices, validation_indices = _make_stratified_split(
        targets=augmented_training_dataset.targets,
        validation_fraction=DATA_CONFIG["validation_fraction"],
        seed=DATA_CONFIG["split_seed"],
    )

    training_subset = Subset(
        augmented_training_dataset,
        train_indices,
    )
    validation_subset = Subset(
        evaluation_training_dataset,
        validation_indices,
    )

    protocol_name = DATA_CONFIG["primary"]["default_protocol"]
    classes_per_task = DATA_CONFIG["primary"]["task_protocols"][
        protocol_name
    ]["classes_per_task"]

    all_training_targets = np.asarray(
        augmented_training_dataset.targets,
        dtype=np.int64,
    )
    training_task_ids = (
        all_training_targets[np.asarray(train_indices)] // classes_per_task
    )
    validation_task_ids = (
        all_training_targets[np.asarray(validation_indices)]
        // classes_per_task
    )
    clean_test_task_ids = (
        np.asarray(clean_test_dataset.targets, dtype=np.int64)
        // classes_per_task
    )

    corrupted_test_dataset = _load_cached_cifar10c(
        data_root=data_root,
        transform=evaluation_transform,
    )

    train = TaggedDataset(
        training_subset,
        source="cifar100_train",
        task_ids=training_task_ids,
    )
    val = TaggedDataset(
        validation_subset,
        source="cifar100_validation",
        task_ids=validation_task_ids,
    )
    cifar100_test = TaggedDataset(
        clean_test_dataset,
        source="cifar100_clean_test",
        task_ids=clean_test_task_ids,
    )
    cifar10c_test = TaggedDataset(
        corrupted_test_dataset,
        source="cifar10_corrupted_test",
    )

    return {
        "train": train,
        "val": val,
        "test": ConcatDataset([cifar100_test, cifar10c_test]),
    }

