def _parameter_counts(model: nn.Module) -> Tuple[int, int]:
    total = sum(parameter.numel() for parameter in model.parameters())
    trainable = sum(
        parameter.numel()
        for parameter in model.parameters()
        if parameter.requires_grad
    )
    return total, trainable


def _build_torchvision_vit(num_classes: int) -> nn.Module:
    try:
        model = vit_b_16(weights=ViT_B_16_Weights.DEFAULT)
    except Exception as exc:
        warnings.warn(
            "Pretrained torchvision ViT-B/16 weights were unavailable; using "
            f"random initialization. Original error: {exc}",
            RuntimeWarning,
        )
        model = vit_b_16(weights=None)

    input_features = model.heads.head.in_features
    model.heads.head = nn.Linear(input_features, num_classes)
    return model


def _unpack_batch(batch):
    if isinstance(batch, dict):
        return batch["image"], batch["label"]
    return batch[0], batch[1]


class ContinualBaseline(nn.Module):
    def __init__(self, network: nn.Module) -> None:
        super().__init__()
        self.network = network

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        return self.network(images)

    def observe(
        self,
        images: torch.Tensor,
        targets: torch.Tensor,
    ) -> torch.Tensor:
        return F.cross_entropy(self(images), targets)

    def end_task(self, *args, **kwargs) -> None:
        return None


class FineTuningBaseline(ContinualBaseline):
    pass


class EWCBaseline(ContinualBaseline):
    def __init__(
        self,
        network: nn.Module,
        ewc_lambda: float = 1000.0,
    ) -> None:
        super().__init__(network)
        self.ewc_lambda = float(ewc_lambda)
        self.num_consolidated_tasks = 0

        for name, parameter in self.network.named_parameters():
            safe_name = self._safe_name(name)
            self.register_buffer(
                f"ewc_mean_{safe_name}",
                torch.zeros_like(parameter),
            )
            self.register_buffer(
                f"ewc_fisher_{safe_name}",
                torch.zeros_like(parameter),
            )

    @staticmethod
    def _safe_name(name: str) -> str:
        return name.replace(".", "__")

    def penalty(self) -> torch.Tensor:
        reference = next(self.network.parameters())
        result = reference.new_zeros(())

        if self.num_consolidated_tasks == 0:
            return result

        for name, parameter in self.network.named_parameters():
            safe_name = self._safe_name(name)
            mean = getattr(self, f"ewc_mean_{safe_name}")
            fisher = getattr(self, f"ewc_fisher_{safe_name}")
            result = result + (fisher * (parameter - mean).square()).sum()

        return 0.5 * self.ewc_lambda * result

    def observe(
        self,
        images: torch.Tensor,
        targets: torch.Tensor,
    ) -> torch.Tensor:
        return F.cross_entropy(self(images), targets) + self.penalty()

    @torch.enable_grad()
    def consolidate(
        self,
        loader: DataLoader,
        max_batches: Optional[int] = None,
    ) -> None:
        device = next(self.network.parameters()).device
        previous_mode = self.network.training
        self.network.eval()

        fisher = {
            name: torch.zeros_like(parameter)
            for name, parameter in self.network.named_parameters()
        }
        processed_batches = 0

        for batch_index, batch in enumerate(loader):
            if max_batches is not None and batch_index >= max_batches:
                break

            images, targets = _unpack_batch(batch)
            images = images.to(device, non_blocking=True)
            targets = targets.to(device, non_blocking=True).long()

            self.network.zero_grad(set_to_none=True)
            loss = F.cross_entropy(self.network(images), targets)
            loss.backward()

            for name, parameter in self.network.named_parameters():
                if parameter.grad is not None:
                    fisher[name].add_(parameter.grad.detach().square())

            processed_batches += 1

        if processed_batches == 0:
            raise ValueError("Cannot consolidate EWC using an empty loader.")

        with torch.no_grad():
            old_task_count = self.num_consolidated_tasks
            new_task_count = old_task_count + 1

            for name, parameter in self.network.named_parameters():
                safe_name = self._safe_name(name)
                stored_mean = getattr(self, f"ewc_mean_{safe_name}")
                stored_fisher = getattr(self, f"ewc_fisher_{safe_name}")
                current_fisher = fisher[name] / processed_batches

                if old_task_count == 0:
                    stored_fisher.copy_(current_fisher)
                else:
                    stored_fisher.mul_(
                        old_task_count / new_task_count
                    ).add_(current_fisher / new_task_count)

                stored_mean.copy_(parameter.detach())

        self.num_consolidated_tasks += 1
        self.network.train(previous_mode)

    def end_task(
        self,
        loader: DataLoader,
        max_batches: Optional[int] = None,
    ) -> None:
        self.consolidate(loader, max_batches=max_batches)


class ReservoirReplayBuffer:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("Replay capacity must be positive.")

        self.capacity = int(capacity)
        self.images = []
        self.targets = []
        self.num_seen = 0

    def __len__(self) -> int:
        return len(self.targets)

    @torch.no_grad()
    def add(
        self,
        images: torch.Tensor,
        targets: torch.Tensor,
    ) -> None:
        cpu_images = images.detach().cpu()
        cpu_targets = targets.detach().cpu().long()

        for image, target in zip(cpu_images, cpu_targets):
            self.num_seen += 1

            if len(self.targets) < self.capacity:
                self.images.append(image.clone())
                self.targets.append(target.clone())
                continue

            replacement = random.randrange(self.num_seen)
            if replacement < self.capacity:
                self.images[replacement] = image.clone()
                self.targets[replacement] = target.clone()

    def sample(
        self,
        batch_size: int,
        device: torch.device,
    ) -> Optional[Tuple[torch.Tensor, torch.Tensor]]:
        if len(self) == 0:
            return None

        sample_size = min(int(batch_size), len(self))
        indices = random.sample(range(len(self)), sample_size)

        images = torch.stack([self.images[index] for index in indices])
        targets = torch.stack([self.targets[index] for index in indices])

        return (
            images.to(device, non_blocking=True),
            targets.to(device, non_blocking=True),
        )


class ExperienceReplayBaseline(ContinualBaseline):
    def __init__(
        self,
        network: nn.Module,
        buffer_size: int = 2000,
        replay_batch_size: int = 32,
    ) -> None:
        super().__init__(network)
        self.replay_buffer = ReservoirReplayBuffer(buffer_size)
        self.replay_batch_size = int(replay_batch_size)

    def observe(
        self,
        images: torch.Tensor,
        targets: torch.Tensor,
    ) -> torch.Tensor:
        replay_batch = self.replay_buffer.sample(
            self.replay_batch_size,
            images.device,
        )

        if replay_batch is None:
            combined_images = images
            combined_targets = targets
        else:
            replay_images, replay_targets = replay_batch
            combined_images = torch.cat((images, replay_images), dim=0)
            combined_targets = torch.cat((targets, replay_targets), dim=0)

        loss = F.cross_entropy(
            self(combined_images),
            combined_targets,
        )
        self.replay_buffer.add(images, targets)
        return loss


class PackNetBaseline(ContinualBaseline):
    def __init__(
        self,
        network: nn.Module,
        prune_fraction: float = 0.5,
    ) -> None:
        super().__init__(network)

        if not 0.0 < prune_fraction < 1.0:
            raise ValueError("prune_fraction must lie strictly between 0 and 1.")

        self.prune_fraction = float(prune_fraction)
        self.task_masks: Dict[int, Dict[str, torch.Tensor]] = {}
        self.current_task = 0

        for name, parameter in self.network.named_parameters():
            self.register_buffer(
                f"packnet_frozen_{self._safe_name(name)}",
                torch.zeros_like(parameter, dtype=torch.bool),
            )

    @staticmethod
    def _safe_name(name: str) -> str:
        return name.replace(".", "__")

    def _frozen_mask(self, name: str) -> torch.Tensor:
        return getattr(
            self,
            f"packnet_frozen_{self._safe_name(name)}",
        )

    @torch.no_grad()
    def mask_frozen_gradients(self) -> None:
        for name, parameter in self.network.named_parameters():
            if parameter.grad is not None:
                parameter.grad.masked_fill_(
                    self._frozen_mask(name),
                    0.0,
                )

    @torch.no_grad()
    def prune_and_freeze(self) -> None:
        current_task_mask = {}

        for name, parameter in self.network.named_parameters():
            frozen_mask = self._frozen_mask(name)
            available_mask = ~frozen_mask

            if not available_mask.any():
                current_task_mask[name] = torch.zeros_like(frozen_mask)
                continue

            available_magnitudes = parameter.abs()[available_mask]
            keep_count = max(
                1,
                int(
                    round(
                        available_magnitudes.numel()
                        * (1.0 - self.prune_fraction)
                    )
                ),
            )

            if keep_count >= available_magnitudes.numel():
                threshold = available_magnitudes.min()
            else:
                threshold = torch.topk(
                    available_magnitudes,
                    k=keep_count,
                    largest=True,
                    sorted=False,
                ).values.min()

            new_frozen = (
                available_mask
                & (parameter.abs() >= threshold)
            )
            new_pruned = available_mask & ~new_frozen

            parameter.masked_fill_(new_pruned, 0.0)
            frozen_mask.logical_or_(new_frozen)
            current_task_mask[name] = new_frozen.clone()

        self.task_masks[self.current_task] = current_task_mask
        self.current_task += 1

    def end_task(self, *args, **kwargs) -> None:
        self.prune_and_freeze()


class HuggingFaceViTClassifier(nn.Module):
    def __init__(
        self,
        backbone: nn.Module,
        hidden_size: int,
        num_classes: int,
    ) -> None:
        super().__init__()
        self.backbone = backbone
        self.classifier = nn.Linear(hidden_size, num_classes)

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        outputs = self.backbone(pixel_values=images)
        features = outputs.last_hidden_state[:, 0]
        return self.classifier(features)


def _build_lora_vit(num_classes: int) -> nn.Module:
    try:
        from peft import LoraConfig, get_peft_model
        from transformers import ViTConfig, ViTModel
    except ImportError as exc:
        raise ImportError(
            "The LoRA baseline requires optional packages 'peft' and "
            "'transformers'. Install both packages to enable this baseline."
        ) from exc

    pretrained_name = "google/vit-base-patch16-224-in21k"

    try:
        backbone = ViTModel.from_pretrained(
            pretrained_name,
            local_files_only=True,
        )
    except Exception as exc:
        warnings.warn(
            "Cached pretrained HuggingFace ViT weights were unavailable; "
            f"using a randomly initialized ViTConfig. Original error: {exc}",
            RuntimeWarning,
        )
        backbone = ViTModel(ViTConfig())

    model = HuggingFaceViTClassifier(
        backbone=backbone,
        hidden_size=backbone.config.hidden_size,
        num_classes=num_classes,
    )

    leaf_module_names = {
        name.rsplit(".", 1)[-1]
        for name, _ in model.named_modules()
    }

    requested_targets = ["q_proj", "v_proj"]
    if all(name in leaf_module_names for name in requested_targets):
        target_modules = requested_targets
    elif {"query", "value"}.issubset(leaf_module_names):
        target_modules = ["query", "value"]
        warnings.warn(
            "HuggingFace ViT uses attention module names 'query' and 'value'; "
            "these architecture-equivalent targets replace q_proj and v_proj.",
            RuntimeWarning,
        )
    else:
        raise RuntimeError(
            "The selected ViT exposes neither q_proj/v_proj nor query/value "
            "attention modules, so LoRA cannot be applied safely."
        )

    config = LoraConfig(
        r=16,
        lora_alpha=32,
        lora_dropout=0.05,
        target_modules=target_modules,
        bias="none",
        modules_to_save=["classifier"],
    )
    return get_peft_model(model, config)


def get_baselines(num_classes, device="cuda") -> dict:
    if not isinstance(num_classes, int) or num_classes <= 1:
        raise ValueError(
            f"num_classes must be an integer greater than 1; got {num_classes!r}."
        )

    if str(device).startswith("cuda") and not torch.cuda.is_available():
        warnings.warn(
            "CUDA was requested but is unavailable; falling back to CPU.",
            RuntimeWarning,
        )
        device = "cpu"

    target_device = torch.device(device)
    template = _build_torchvision_vit(num_classes)

    baselines = {
        "fine_tuning": FineTuningBaseline(copy.deepcopy(template)),
        "ewc": EWCBaseline(
            copy.deepcopy(template),
            ewc_lambda=BASELINES_CONFIG["ewc"]["ewc_lambda"],
        ),
        "experience_replay": ExperienceReplayBaseline(
            copy.deepcopy(template),
            buffer_size=BASELINES_CONFIG["experience_replay"]["buffer_size"],
            replay_batch_size=BASELINES_CONFIG[
                "experience_replay"
            ]["replay_batch_size"],
        ),
        "packnet": PackNetBaseline(
            copy.deepcopy(template),
            prune_fraction=BASELINES_CONFIG["packnet"]["prune_fraction"],
        ),
    }

    del template

    try:
        baselines["lora"] = ContinualBaseline(
            _build_lora_vit(num_classes)
        )
        BASELINES_CONFIG["lora"]["available"] = True
        BASELINES_CONFIG["lora"]["unavailable_reason"] = None
    except (ImportError, RuntimeError) as exc:
        BASELINES_CONFIG["lora"]["available"] = False
        BASELINES_CONFIG["lora"]["unavailable_reason"] = str(exc)
        warnings.warn(
            f"LoRA baseline is unavailable and will be omitted: {exc}",
            RuntimeWarning,
        )

    for method_name, model in baselines.items():
        try:
            model.to(target_device)
        except RuntimeError as exc:
            if "out of memory" in str(exc).lower():
                raise RuntimeError(
                    f"Moving all baselines to {target_device} exhausted memory "
                    f"while processing {method_name!r}. Instantiate or train "
                    "the ViT baselines one at a time."
                ) from exc
            raise

        total, trainable = _parameter_counts(model)
        BASELINES_CONFIG[method_name]["param_count"] = total
        BASELINES_CONFIG[method_name][
            "trainable_param_count"
        ] = trainable

    return baselines
